    @Transactional
    public void updateSaleStatusToSold(Long orderId) {
        log.info("판매 상태를 'SOLD'로 변경 시작: orderId={}", orderId);

        // SaleBid 조회
        SaleBid saleBid = saleBidQueryService.findByOrderId(orderId);
